export type ParsedReleaseInstruction<
  TProgram extends string = typeof TESSERA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    order: TAccountMetas[1];
    vault: TAccountMetas[2];
    mint: TAccountMetas[3];
    merchantToken: TAccountMetas[4];
    buyerToken: TAccountMetas[5];
    treasuryToken: TAccountMetas[6];
    merchantAgent: TAccountMetas[7];
    buyerAgent: TAccountMetas[8];
    pair: TAccountMetas[9];
    payer: TAccountMetas[10];
    authority: TAccountMetas[11];
    tokenProgram: TAccountMetas[12];
  };
  data: ReleaseInstructionData;
};

export function parseReleaseInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedReleaseInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      order: getNextAccount(),
      vault: getNextAccount(),
      mint: getNextAccount(),
      merchantToken: getNextAccount(),
      buyerToken: getNextAccount(),
      treasuryToken: getNextAccount(),
      merchantAgent: getNextAccount(),
      buyerAgent: getNextAccount(),
      pair: getNextAccount(),
      payer: getNextAccount(),
      authority: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getReleaseInstructionDataDecoder().decode(instruction.data),
  };
}
